// Word database generator for A Word a Day
// Run: node scripts/generate-words.js
const fs = require('fs');
const path = require('path');

const OUT = path.join(__dirname, '../data/word-a-day/words');

// ─────────────────────────────────────────────────────────
// Helper: assign ids, week, day, slot automatically
// ─────────────────────────────────────────────────────────
function pack(code, tier, weekStart, words) {
  return words.map((w, i) => {
    const weekOffset = Math.floor(i / 21);
    const dayInWeek  = Math.floor((i % 21) / 3) + 1;
    const slot       = (i % 3) + 1;
    const week       = weekStart + weekOffset;
    return {
      id: `${code}-${tier}-${week}-${dayInWeek}-${slot}`,
      tier, week, day: dayInWeek, slot,
      ...w,
    };
  });
}

