// ─────────────────────────────────────────────────────────
// Write files
// ─────────────────────────────────────────────────────────
const langs = [spanish, chinese, japanese, vietnamese, swahili, kikuyu];
langs.forEach(lang => {
  const file = path.join(OUT, `${lang.code}.json`);
  fs.writeFileSync(file, JSON.stringify(lang, null, 2), 'utf8');
  const t1 = lang.words.filter(w => w.tier === 1).length;
  const t2 = lang.words.filter(w => w.tier === 2).length;
  const t3 = lang.words.filter(w => w.tier === 3).length;
  console.log(`✓ ${lang.language}: ${lang.words.length} words (T1:${t1} T2:${t2} T3:${t3})`);
});
console.log('\nDone. Word databases written to data/word-a-day/words/');
